@import url('https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,300;9..40,400;9..40,500;9..40,600;9..40,700&display=swap');


/* ══════════════════════════════════════════════════════════════════════
   DESIGN TOKENS  —  Slate Indigo  ·  Basis: #4C5578
   Farben hier ändern, der Rest passt sich an
   ══════════════════════════════════════════════════════════════════════ */
:root {

  /* ── AKZENTFARBE (Markenfarbe / Brand Primary) ───────────────────────
     Erscheint auf: Buttons, aktiven Tabs, Checkboxen, Rahmen-Highlights,
     Paginierung, Tags, Badges und allen interaktiven Elementen.          */
  --akzent:              #b0b8d8;   /* Hauptfarbe – Buttons & aktive Elemente        */
  --akzent-dunkel:       #8d96be;   /* Hover / gedrückt – etwas dunkler              */
  --akzent-hell:         #eef0f7;   /* Sehr hell – Badge- & Tag-Hintergrund          */
  --akzent-hover:        #dde1f0;   /* Hover-Hintergrund für slate Flächen           */
  --akzent-blass:        #e6e9f5;   /* Blass – sehr helle Rahmen-Akzente             */

  /* ── NAVIGATION (Seitenleiste) ───────────────────────────────────── */
  --nav-farbe:           #31374e;   /* Hintergrundfarbe der Seitenleiste             */
  --nav-hover:           #3d4460;   /* Seitenleiste – Hover-Zustand                  */
  --nav-hintergrund:     var(--nav-farbe);

  /* ── TEXT & ICONS ────────────────────────────────────────────────── */
  --text-gedaempft:      #7c8299;   /* Gedämpft – Labels, Platzhaltertext            */
  --text-schwach:        #9da3b8;   /* Schwach – deaktivierte Elemente, Icons        */

  /* ── GRAUTÖNE (Terminblöcke Typ 3) ──────────────────────────────── */
  --grau-mittel:         #7f8c8d;   /* Grau mittel – Terminblock 3 Basis             */
  --grau-hell:           #a8b6b7;   /* Grau hell – Terminblock 3 Hover               */

  /* ── HINTERGRÜNDE ────────────────────────────────────────────────── */
  --hintergrund-karte:   #ffffff;   /* Karten & Panels – Hintergrund                 */
  --hintergrund-seite:   #f4f5f8;   /* Seiten-Hintergrund (außen) – kühler Ton       */
  --hintergrund-warm:    #f4f5f8;   /* Slate getönter Seiten-Hintergrund             */
  --zeitraster-ungerade: #f7f8fb;   /* Kalender-Zeitraster: ungerade Zeilen          */
  --zeitraster-gerade:   #ffffff;   /* Kalender-Zeitraster: gerade Zeilen            */

  /* ── LINIEN & RAHMEN ─────────────────────────────────────────────── */
  --linie:               #dde0ef;   /* Standard-Trennlinie                           */
  --linie-gestrichelt:   #e5e8f5;   /* Gestrichelte Trennlinie                       */
  --linie-stark:         #d5d9ec;   /* Stärkere Rahmenlinie                          */
  --linie-subtil:        #eceef7;   /* Sehr schwache Trennlinie                      */
  --rahmen:              var(--linie-stark);
  --rahmen-neutral:      #cdd2e0;   /* Neutral – Eingabefelder                       */

  /* ── BESCHRIFTUNGEN ──────────────────────────────────────────────── */
  --zeitachse-text:      #b4b8cc;   /* Zeitachsen-Beschriftung im Kalender           */
  --wochenende-text:     #c2c6d8;   /* Wochenend-Spalten Textfarbe                   */

  /* ── TABELLEN ────────────────────────────────────────────────────── */
  --tabelle-zeile-hover: #f7f8fc;   /* Tabellenzeile – Hover-Hintergrund             */
  --tabelle-kopf:        #f2f3f8;   /* Tabellenkopf – Hintergrund                    */

  /* ── STATUS: FEHLER (Rot) ────────────────────────────────────────── */
  --fehler:              #DC2626;   /* Fehler-Hauptfarbe – Rot                       */
  --fehler-hell:         #FCA5A5;   /* Fehler – helle Variante                       */
  --fehler-hintergrund:  #FEE2E2;   /* Fehler – Hintergrundfarbe                     */
  --fehler-rahmen:       #fda29b;   /* Fehler – Rahmenfarbe                          */
  --fehler-text:         #b42318;   /* Fehler – Textfarbe                            */

  /* ── STATUS: WARNUNG (Gelb) ──────────────────────────────────────── */
  --warnung-hintergrund: #FEF9C3;   /* Warnung – Hintergrundfarbe                    */
  --warnung-rahmen:      #FEF08A;   /* Warnung – Rahmenfarbe                         */
  --warnung-text:        #92400E;   /* Warnung – Textfarbe                           */

  /* ── ALPHA-WERTE: Akzent ─────────────────────────────────────────── */
  --akzent-glow:    color-mix(in srgb, var(--akzent) 40%, transparent);
  --akzent-focus:   color-mix(in srgb, var(--akzent) 18%, transparent);
  --akzent-ring:    color-mix(in srgb, var(--akzent) 30%, transparent);
  --akzent-a02:     color-mix(in srgb, var(--akzent)  2%, transparent);
  --akzent-a04:     color-mix(in srgb, var(--akzent)  4%, transparent);
  --akzent-a08:     color-mix(in srgb, var(--akzent)  8%, transparent);
  --akzent-a10:     color-mix(in srgb, var(--akzent) 10%, transparent);
  --akzent-a12:     color-mix(in srgb, var(--akzent) 12%, transparent);
  --akzent-a15:     color-mix(in srgb, var(--akzent) 15%, transparent);
  --akzent-a20:     color-mix(in srgb, var(--akzent) 20%, transparent);
  --akzent-a25:     color-mix(in srgb, var(--akzent) 25%, transparent);
  --akzent-a30:     color-mix(in srgb, var(--akzent) 30%, transparent);
  --akzent-a35:     color-mix(in srgb, var(--akzent) 35%, transparent);
  --akzent-a50:     color-mix(in srgb, var(--akzent) 50%, transparent);
  --akzent-a60:     color-mix(in srgb, var(--akzent) 60%, transparent);
  --akzent-dk-a20:  color-mix(in srgb, var(--akzent-dunkel) 20%, transparent);
  --akzent-schatten:color-mix(in srgb, var(--akzent-dunkel) 12%, transparent);

  /* ── ALPHA-WERTE: Navigation ─────────────────────────────────────── */
  --nav-a06:        color-mix(in srgb, var(--nav-farbe)  6%, transparent);
  --nav-a10:        color-mix(in srgb, var(--nav-farbe) 10%, transparent);
  --nav-a12:        color-mix(in srgb, var(--nav-farbe) 12%, transparent);

  /* ── ALPHA-WERTE: Schwarz ────────────────────────────────────────── */
  --black-a18:           rgba(0,0,0,0.18);
  --black-a008:          rgba(0,0,0,0.008);

  /* ── ALPHA-WERTE: Weiß (auf dunklen Flächen) ────────────────────── */
  --white-a07:  rgba(255,255,255,0.07);
  --white-a08:  rgba(255,255,255,0.08);
  --white-a09:  rgba(255,255,255,0.09);
  --white-a10:  rgba(255,255,255,0.10);
  --white-a12:  rgba(255,255,255,0.12);
  --white-a13:  rgba(255,255,255,0.13);
  --white-a14:  rgba(255,255,255,0.14);
  --white-a15:  rgba(255,255,255,0.15);
  --white-a18:  rgba(255,255,255,0.18);
  --white-a20:  rgba(255,255,255,0.20);
  --white-a25:  rgba(255,255,255,0.25);
  --white-a28:  rgba(255,255,255,0.28);
  --white-a30:  rgba(255,255,255,0.30);
  --white-a32:  rgba(255,255,255,0.32);
  --white-a40:  rgba(255,255,255,0.40);
  --white-a45:  rgba(255,255,255,0.45);
  --white-a50:  rgba(255,255,255,0.50);
  --white-a55:  rgba(255,255,255,0.55);
  --white-a60:  rgba(255,255,255,0.60);
  --white-a65:  rgba(255,255,255,0.65);
  --white-a70:  rgba(255,255,255,0.70);
  --white-a75:  rgba(255,255,255,0.75);
  --white-a85:  rgba(255,255,255,0.85);
  --white-a90:  rgba(255,255,255,0.90);
  --white-a93:  rgba(255,255,255,0.93);

  /* ── ALPHA-WERTE: Sonstiges ──────────────────────────────────────── */
  --wochenende-overlay:  rgba(242,243,248,0.60);   /* Slate-getönt statt rosa    */
  --fehler-glow:         rgba(220,38,38,0.12);

  /* ── GRADIENTEN: Terminblöcke ────────────────────────────────────── */
  --termin-1-hintergrund: linear-gradient(160deg, var(--nav-farbe),     var(--nav-hover));
  --termin-1-hover:       linear-gradient(160deg, var(--nav-hover),     var(--nav-farbe));
  --termin-2-hintergrund: linear-gradient(160deg, var(--akzent),        var(--akzent-dunkel));
  --termin-2-hover:       linear-gradient(160deg, var(--akzent-hover),  var(--akzent));
  --termin-3-hintergrund: linear-gradient(160deg, var(--text-gedaempft),var(--grau-mittel));
  --termin-3-hover:       linear-gradient(160deg, var(--grau-hell),     var(--text-gedaempft));

  /* ── GRADIENT: Primär-Button ─────────────────────────────────────── */
  --verlauf-button: linear-gradient(135deg, var(--akzent), var(--akzent-dunkel));

  /* ── WEISS (Weiß-Utility) ────────────────────────────────────────── */
  --weiss:              #ffffff;   /* Reines Weiß – Text & Hintergründe             */
  --weiss-warm:         #f7f8fb;   /* Slate-Weiß – subtile Hintergründe             */
  --rosa-subtil:        #e3e6f0;   /* Ersetzt Rosa → helles Slate-Indigo            */
  --akzent-blass-3:     #e8eaf5;   /* Sehr helles Akzent-Slate                      */

  /* ── SLATE (Primäre Dunkelfarbe — ersetzt WINE) ──────────────────── */
  --wine:               #31374e;   /* Dunkles Slate Indigo – Primär                 */
  --wine-2:             #3d4460;   /* Mittleres Slate                               */
  --wine-3:             #4c5578;   /* Kernfarbe Slate Indigo ← HAUPTFARBE           */
  --wine-4:             #38415c;   /* Alternative Slate-Variante                    */
  --wine-tief:          #1e212f;   /* Sehr dunkles Slate                            */
  --wine-lt:            #f2f3f8;   /* Slate-Light – sehr heller Hintergrund         */

  /* ── ALPHA-WERTE: Slate (ehem. Wine) ────────────────────────────── */
  --wine-a04:   color-mix(in srgb, var(--wine)  4%, transparent);
  --wine-a05:   color-mix(in srgb, var(--wine)  5%, transparent);
  --wine-a07:   color-mix(in srgb, var(--wine)  7%, transparent);
  --wine-a08:   color-mix(in srgb, var(--wine)  8%, transparent);
  --wine-a10:   color-mix(in srgb, var(--wine) 10%, transparent);
  --wine-a12:   color-mix(in srgb, var(--wine) 12%, transparent);
  --wine-a15:   color-mix(in srgb, var(--wine) 15%, transparent);
  --wine-a20:   color-mix(in srgb, var(--wine) 20%, transparent);
  --wine-a25:   color-mix(in srgb, var(--wine) 25%, transparent);
  --wine-a30:   color-mix(in srgb, var(--wine) 30%, transparent);
  --wine-a40:   color-mix(in srgb, var(--wine) 40%, transparent);
  --wine-a50:   color-mix(in srgb, var(--wine) 50%, transparent);

}


/* ════════════════════════════════════════════════════════════════
   GLOBAL FONT
   ════════════════════════════════════════════════════════════════ */
* { font-family: 'DM Sans', system-ui, -apple-system, sans-serif !important; -webkit-font-smoothing: antialiased !important; }

i[class*="fa-"], .fas, .far, .fab, .fal {
  font-family: "Font Awesome 5 Free", "Font Awesome 5 Brands" !important;
}

/* ════════════════════════════════════════════════════════════════
   Section 126 – Conversations Top-Navigation
   Scope: .topmenu-nav
   ════════════════════════════════════════════════════════════════ */

/* Aktiver Tab → wine */
.topmenu-nav .topmenu-navitem.active {
  color:        var(--akzent-dunkel) !important;
  border-color: var(--akzent-dunkel) !important;
}

/* Aktiver Tab Unterstrich → wine */
.topmenu-nav .topmenu-navitem.active::after {
  background-color: var(--akzent-dunkel) !important;
  border-color:     var(--akzent-dunkel) !important;
}

/* Hover → wine */
.topmenu-nav .topmenu-navitem:hover {
  color: var(--akzent) !important;
}

/* ════════════════════════════════════════════════════════════════
   8 · MANAGE VIEW DRAWER (#calendar-view-filter-drawer)
   Radio-Regeln (.hl-radio/.n-radio) → verschoben in Section 30 · GLOBAL RADIO BUTTONS
 ════════════════════════════════════════════════════════════════ */

#calendar-view-filter-drawer {
  background: var(--hintergrund-karte) !important; border-left: 1.5px solid var(--linie) !important;
  box-shadow: -6px 0 24px var(--nav-a06) !important;
}
#calendar-view-filter-drawer > div:first-child {
  height: 52px !important; padding: 0 16px !important; border-bottom: 1.5px solid var(--linie) !important;
  display: flex !important; align-items: center !important; justify-content: space-between !important;
}
#calendar-view-filter-drawer .text-base.font-semibold {
  font-size: 10px !important; font-weight: 800 !important; letter-spacing: 0.16em !important;
  text-transform: uppercase !important; color: var(--nav-farbe) !important;
}
button#close-filter-drawer svg { color: var(--text-schwach) !important; }
button#close-filter-drawer:hover svg { color: var(--akzent-dunkel) !important; }

#calendar-view-filter-drawer .bg-primary-25 {
  background: var(--hintergrund-seite) !important; border-radius: 12px !important; padding: 14px !important;
}
#calendar-view-filter-drawer .text-sm.font-medium.text-gray-900 {
  font-size: 10px !important; font-weight: 700 !important; letter-spacing: 0.12em !important;
  text-transform: uppercase !important; color: var(--text-schwach) !important;
}

/* Radio */
#calendar-view-filter-drawer .flex.items-center.justify-between > .text-sm.font-medium {
  font-size: 10px !important; font-weight: 800 !important; letter-spacing: 0.15em !important;
  text-transform: uppercase !important; color: var(--text-schwach) !important;
}
button#clear-all-filters-btn span,
button#clear-all-filters-btn svg,
#clear-all-filters-btn *, #clear-all-filters-btn div { color: var(--akzent-dunkel) !important; font-size: 12px !important; font-weight: 600 !important; }

/* Search */
#filter-search-input .n-input-wrapper {
  background: var(--hintergrund-seite) !important; border: 1px solid var(--linie) !important; border-radius: 8px !important;
}
#filter-search-input .n-input__border, #filter-search-input .n-input__state-border { display: none !important; }
#filter-search-input input { font-size: 12px !important; color: var(--nav-hover) !important; }
#filter-search-input input::placeholder { color: var(--text-schwach) !important; }
#filter-search-input svg { color: var(--text-schwach) !important; }

/* USERS badge */
#calendar-view-filter-drawer .bg-blue-100 {
  background: var(--akzent-hell) !important; color: var(--nav-farbe) !important;
  font-weight: 800 !important; font-size: 10px !important; padding: 1px 8px !important; border-radius: 100px !important;
}
#calendar-view-filter-drawer button.flex.items-center.gap-1.w-full.text-left {
  color: var(--nav-farbe) !important; font-weight: 700 !important; font-size: 14px !important;
}

/* Barber rows */
#calendar-view-filter-drawer button.gap-1.py-1.text-gray-600,
#calendar-view-filter-drawer button.gap-1.py-1 {
  padding: 6px 8px !important; border-radius: 8px !important; transition: background 0.12s !important;
  color: var(--nav-hover) !important; font-size: 13px !important; width: 100% !important;
}
#calendar-view-filter-drawer button.gap-1.py-1:hover,
#calendar-view-filter-drawer button.gap-1.py-1.text-gray-600:hover { background: var(--hintergrund-seite) !important; }
#calendar-view-filter-drawer span.text-\[13px\] { font-size: 13px !important; font-weight: 500 !important; color: var(--nav-hover) !important; }
#calendar-view-filter-drawer span.h-4.w-4 { border-radius: 5px !important; }
#calendar-view-filter-drawer .border-\[0\.5px\] { border-color: var(--linie) !important; }

/* ============================================================
   SECTION 96 — Launchpad Page(Onboarding/Setup)
   Scope: #launchpad
   ============================================================ */

/* ── Page Background ── */
#launchpad {
  background-color: var(--hintergrund-seite) !important;
}
#launchpad .container-fluid {
  background-color: var(--hintergrund-seite) !important;
}

/* ── Titel ── */
#launchpad .launchpad-title p {
  color: var(--nav-farbe) !important;
  font-weight: 700 !important;
}

/* ── Item Container ── */
#launchpad .launchpad-item-container {
  background-color: var(--hintergrund-karte) !important;
  border: 1px solid var(--linie-stark) !important;
  border-radius: 12px !important;
  overflow: hidden !important;
}

/* ── Einzelne Item Rows ── */
#launchpad .launchpad-item-sub-container {
  background-color: var(--hintergrund-karte) !important;
  transition: background-color 0.2s !important;
}
#launchpad .launchpad-item-sub-container:hover {
  background-color: var(--akzent-hell) !important;
}
#launchpad .launchpad-bottom-border {
  border-bottom: 1px solid var(--linie-stark) !important;
}

/* ── Item Text ── */
#launchpad .item-info .font-normal {
  color: var(--text-gedaempft) !important;
}
#launchpad .item-info span {
  color: var(--text-schwach) !important;
}

/* ── Buttons (green-btn → wine) ── */
#launchpad .green-btn,
#launchpad .green-filled-button {
  background-color: var(--akzent) !important;
  background:       var(--akzent) !important;
  border: 1px solid var(--akzent) !important;
  color: var(--weiss) !important;
  border-radius: 8px !important;
  transition: background-color 0.2s, border-color 0.2s !important;
}
#launchpad .green-btn:hover,
#launchpad .green-filled-button:hover {
  background-color: var(--akzent-dunkel) !important;
  background:       var(--akzent-dunkel) !important;
  border-color:     var(--akzent-dunkel) !important;
}
#launchpad .green-btn span,
#launchpad .green-filled-button span {
  color: var(--weiss) !important;
}

/* ── Integration Icons — leichte Abrundung ── */
#launchpad .integration-icon {
  border-radius: 8px !important;
}

/* ============================================================
   SECTION 97 — Launchpad Modals
   Deckt ab: FB/GMB Hinweis, Mobile, Chat-Widget, Benutzer hinzufügen
   ============================================================ */

/* ── Gemeinsamer Modal Container ── */
.gmb-container,
.mobile-container,
#chat-widget-modal,
.modal-container {
  background-color: var(--hintergrund-karte) !important;
  border: 1px solid var(--linie-stark) !important;
  border-radius: 12px !important;
}

/* ── fb-container (innerer Wrapper) ── */
.gmb-container .fb-container {
  background-color: var(--hintergrund-karte) !important;
}

/* ── Titel & Texte ── */
.fb-container .fb-title,
.mobile-container .mobile-sub-title {
  color: var(--nav-farbe) !important;
  font-weight: 600 !important;
}
.fb-container .fb-sub-title,
#chat-widget-modal .fb-container > div {
  color: var(--text-gedaempft) !important;
}

/* ── Text-Inputs (hl-text-input) ── */
.hl-text-input {
  border: 1px solid var(--linie-stark) !important;
  border-radius: 8px !important;
  color: var(--nav-hover) !important;
  background-color: var(--weiss) !important;
  transition: border-color 0.2s, box-shadow 0.2s !important;
}
.hl-text-input:focus {
  border-color: var(--akzent) !important;
  box-shadow: 0 0 0 2px var(--akzent-ring) !important;
  outline: none !important;
}
.hl-text-input::placeholder {
  color: var(--text-schwach) !important;
}
/* Override Tailwind-Ring-Klassen (focus:ring-curious-blue-500) */
.hl-text-input.focus\:ring-curious-blue-500:focus,
.hl-text-input.focus\:border-curious-blue-500:focus {
  --tw-ring-color: var(--akzent-ring) !important;
  border-color: var(--akzent) !important;
}

/* Form Labels */
.fb-container label,
.mobile-container label,
.modal-container label,
.card label {
  color: var(--nav-farbe) !important;
  font-weight: 500 !important;
}

/* ── Primäre Buttons (btn-primary, launchpad-filled-button, launchpad-blue-btn) ── */
.btn.btn-primary,
.btn.btn-primary.active,
.launchpad-filled-button,
.launchpad-blue-btn {
  background-color: var(--akzent) !important;
  background:       var(--akzent) !important;
  border: 1px solid var(--akzent) !important;
  color: var(--weiss) !important;
  border-radius: 8px !important;
  transition: background-color 0.2s, border-color 0.2s !important;
}
.btn.btn-primary:hover,
.btn.btn-primary.active:hover,
.launchpad-filled-button:hover,
.launchpad-blue-btn:hover {
  background-color: var(--akzent-dunkel) !important;
  background:       var(--akzent-dunkel) !important;
  border-color:     var(--akzent-dunkel) !important;
}
.btn.btn-primary span,
.launchpad-filled-button span,
.launchpad-blue-btn span {
  color: var(--weiss) !important;
}
/* Disabled state */
.btn.btn-primary:disabled,
.btn.btn-primary[disabled],
.launchpad-filled-button:disabled,
.launchpad-blue-btn:disabled {
  background-color: var(--akzent) !important;
  opacity: 0.5 !important;
  cursor: not-allowed !important;
}

/* ── "Ich habe es verstanden" Button ── */
.fb-container .yes-button {
  background-color: var(--akzent) !important;
  background:       var(--akzent) !important;
  border-color:     var(--akzent) !important;
  color: var(--weiss) !important;
  border-radius: 8px !important;
}
.fb-container .yes-button:hover {
  background-color: var(--akzent-dunkel) !important;
  background:       var(--akzent-dunkel) !important;
  border-color:     var(--akzent-dunkel) !important;
}

/* ── Modal Container (Benutzer hinzufügen) ── */
.modal-container .modal-close-icon {
  color: var(--text-gedaempft) !important;
  transition: color 0.2s !important;
}
.modal-container .modal-close-icon:hover {
  color: var(--akzent-dunkel) !important;
}

/* Card */
.modal-container .card {
  background-color: var(--hintergrund-karte) !important;
  border: none !important;
}
.modal-container .card-header {
  background-color: var(--hintergrund-karte) !important;
  border-bottom: 1px solid var(--linie-stark) !important;
}
.modal-container .card-header h3 {
  color: var(--nav-farbe) !important;
}
.modal-container .card-body {
  color: var(--text-gedaempft) !important;
  background-color: var(--hintergrund-karte) !important;
}
.modal-container .card-body span {
  color: var(--text-schwach) !important;
}
.modal-container .card-footer {
