/* ════════════════════════════════════════════════════════════════
   69 · TERMIN BUCHEN MODAL — v4 (Book Appointment)
   Ancestor: .n-card.hl-modal (max specificity, beats NaïveUI inline)
   ════════════════════════════════════════════════════════════════ */

/* ════════════════════════════════════════════════════════════════
   69.1 · MODAL SHELL
   ════════════════════════════════════════════════════════════════ */

.n-card.hl-modal {
  background: var(--hintergrund-karte) !important;
  border: 1px solid var(--linie-stark) !important;
  border-radius: 14px !important;
  box-shadow: 0 12px 48px var(--nav-a12) !important;
  --n-color: var(--hintergrund-karte) !important;
  --n-color-modal: var(--hintergrund-karte) !important;
  --n-border-color: var(--linie-stark) !important;
  --n-text-color: var(--nav-hover) !important;
  --n-title-text-color: var(--nav-farbe) !important;
}

/* ── Header */
.n-card.hl-modal .n-card-header {
  background: var(--hintergrund-karte) !important;
  border-bottom: 1px solid var(--linie-stark) !important;
  border-radius: 14px 14px 0 0 !important;
  padding-bottom: 14px !important;
