.d-flex.bar .view.active svg {
  color: var(--akzent-dunkel) !important;
  stroke: var(--akzent-dunkel) !important;
}

/* ── Fix: Views-Bar aktiver Tab ::after blauer Strich → weg ── */
.d-flex.view.cursor-pointer.active::after,
.view.active::after {
  display: none !important;
  content: none !important;
  border: none !important;
  background: none !important;
}

/* ── Fix: Pagination Buttons Focus-Ring blau → wine ── */
.tabulator-page:focus,
.tabulator-page:focus-visible {
  outline: none !important;
  box-shadow: 0 0 0 2px var(--akzent-ring) !important;
  border-color: var(--akzent) !important;
}
