.tabulator-page[disabled]:focus-visible {
  outline: none !important;
  box-shadow: none !important;
  border-color: var(--linie-stark) !important;
}

/* ── Fix: Aktiver Pagination Button Border → wine ── */
button.tabulator-page.active,
button.tabulator-page.active:hover,
button.tabulator-page.active:focus,
button.tabulator-page.active:focus-visible {
  background-color: var(--akzent) !important;
  border-color: var(--akzent) !important;
  color: var(--weiss) !important;
  outline: none !important;
  box-shadow: none !important;
}
