  color: var(--weiss) !important;
  outline: none !important;
}
.my-table.tabulator .tabulator-footer .tabulator-paginator button.tabulator-page:not(.active):not([disabled]) {
  border: 1px solid var(--linie-stark) !important;
  color: var(--nav-hover) !important;
