  color: var(--akzent-dunkel) !important;
}

/* ── Kartenlayout Label ── */
.hr-drawer-content-wrapper:has(.crm-opportunities-card-wrapper) .font-medium {
  color: var(--nav-farbe) !important;
}

/* ── Tabs (Felder / Schnelle Aktivitäten) ── */
.hr-drawer-content-wrapper:has(.crm-opportunities-card-wrapper) .hr-tabs {
  --n-bar-color:             var(--akzent) !important;
  --n-tab-text-color-active: var(--akzent-dunkel) !important;
