  border-color: var(--akzent) !important;
}
.hr-drawer-content-wrapper:has(.crm-opportunities-card-wrapper) #manage-fields-cancel .hr-button__content {
  color: var(--nav-hover) !important;
}
.hr-drawer-content-wrapper:has(.crm-opportunities-card-wrapper) #manage-fields-cancel:hover .hr-button__content {
  color: var(--akzent-dunkel) !important;
}
/* Apply (Primary → wine) */
.hr-drawer-content-wrapper:has(.crm-opportunities-card-wrapper) #manage-fields-apply {
  background-image: linear-gradient(var(--akzent), var(--akzent)) !important;
  background-color: var(--akzent) !important;
}
.hr-drawer-content-wrapper:has(.crm-opportunities-card-wrapper) #manage-fields-apply .hr-button__border {
  border: 1px solid var(--akzent) !important;
  border-radius: 6px !important;
}
.hr-drawer-content-wrapper:has(.crm-opportunities-card-wrapper) #manage-fields-apply .hr-button__content {
  color: var(--hintergrund-karte) !important;
}
