}

/* ============================================================
   SECTION 86 · CRM OPPORTUNITIES — FILTER DRAWER
   ============================================================
   ZWEI VIEWS — beide im selben Drawer:
   86-A  Haupt-Filterliste  → has(#assigned_to)
   86-B  Sub-Panel          → has(#data-back)
         (wenn Sub-Panel offen, ist #assigned_to nicht im DOM!)
   ============================================================ */

/* ════════════════════════════════════════════════════════════════
   SHARED — Shell, Header, Icon, Close
   ════════════════════════════════════════════════════════════════ */

/* ── Shell ── */
.hr-drawer-content-wrapper:has(#assigned_to) .hr-drawer-content,
.hr-drawer-content-wrapper:has(#data-back) .hr-drawer-content {
  background-color: var(--hintergrund-karte) !important;
}

/* ── Header ── */
.hr-drawer-content-wrapper:has(#assigned_to) .hr-drawer-header,
.hr-drawer-content-wrapper:has(#data-back) .hr-drawer-header {
  border-bottom: 1px solid var(--linie-stark) !important;
  background-color: var(--hintergrund-karte) !important;
}
.hr-drawer-content-wrapper:has(#assigned_to) .ui-drawer-title,
.hr-drawer-content-wrapper:has(#data-back) .ui-drawer-title {
  color: var(--nav-farbe) !important;
  font-weight: 700 !important;
  font-size: 16px !important;
}
.hr-drawer-content-wrapper:has(#assigned_to) .ui-drawer-description,
.hr-drawer-content-wrapper:has(#data-back) .ui-drawer-description {
  color: var(--text-gedaempft) !important;
  font-size: 13px !important;
}

/* ── Header Icon ── */
/* Rechteck → transparent */
.hr-drawer-content-wrapper:has(#assigned_to) .ui-drawer-header-icon .ui-icon-container,
.hr-drawer-content-wrapper:has(#data-back) .ui-drawer-header-icon .ui-icon-container {
  background: transparent !important;
}
/* Outer Circle (::before pseudo) → wine */
.hr-drawer-content-wrapper:has(#assigned_to) .ui-drawer-header-icon .icon-primary::before,
.hr-drawer-content-wrapper:has(#data-back) .ui-drawer-header-icon .icon-primary::before {
  background-color: var(--akzent) !important;
}
/* Inner Circle (::after pseudo) → wine-lt */
.hr-drawer-content-wrapper:has(#assigned_to) .ui-drawer-header-icon .icon-primary::after,
.hr-drawer-content-wrapper:has(#data-back) .ui-drawer-header-icon .icon-primary::after {
  background-color: var(--akzent-hell) !important;
}
/* SVG → wine */
.hr-drawer-content-wrapper:has(#assigned_to) .ui-drawer-header-icon svg,
.hr-drawer-content-wrapper:has(#data-back) .ui-drawer-header-icon svg {
  stroke: var(--akzent) !important;
  color: var(--akzent) !important;
}
/* .icon direkt → kein eigener Hintergrund */
.hr-drawer-content-wrapper:has(#assigned_to) .ui-drawer-header-icon .icon,
.hr-drawer-content-wrapper:has(#data-back) .ui-drawer-header-icon .icon {
  background: transparent !important;
}

/* ── Close Button ── */
.hr-drawer-content-wrapper:has(#assigned_to) .hr-drawer-header__close,
.hr-drawer-content-wrapper:has(#data-back) .hr-drawer-header__close {
  color: var(--text-gedaempft) !important;
  border-radius: 50% !important;
  transition: background 0.15s, color 0.15s !important;
}
.hr-drawer-content-wrapper:has(#assigned_to) .hr-drawer-header__close:hover,
.hr-drawer-content-wrapper:has(#data-back) .hr-drawer-header__close:hover {
  background-color: var(--akzent-hell) !important;
  color: var(--akzent) !important;
}

/* ════════════════════════════════════════════════════════════════
   86-A · HAUPT-FILTERLISTE — has(#assigned_to)
   ════════════════════════════════════════════════════════════════ */

/* ── Filter Rows — wine bg, weiße Schrift + Chevron ── */
.hr-drawer-content-wrapper:has(#assigned_to) .mb-3.flex.h-12.rounded-md {
  background-color: var(--akzent) !important;
  border-radius: 8px !important;
  transition: background 0.15s !important;
}
.hr-drawer-content-wrapper:has(#assigned_to) .mb-3.flex.h-12.rounded-md:hover {
  background-color: var(--akzent-dunkel) !important;
}
/* Label Text weiß */
.hr-drawer-content-wrapper:has(#assigned_to) .mb-3.flex.h-12 .font-medium,
.hr-drawer-content-wrapper:has(#assigned_to) .mb-3.flex.h-12 .font-medium > div > div:first-child {
  color: var(--hintergrund-karte) !important;
  font-size: 14px !important;
}
