  background-color: var(--white-a25) !important;
}
.hr-drawer-content-wrapper:has(#assigned_to) .text-blue-500 {
  color: var(--hintergrund-karte) !important;
}

/* ════════════════════════════════════════════════════════════════
   86-B · SUB-PANEL — has(#data-back)
   ════════════════════════════════════════════════════════════════ */

/* ── Sticky Header ── */
