  border-radius: 3px !important;
  background-color: var(--hintergrund-karte) !important;
}
.hr-drawer-content-wrapper:has(#data-back) .hr-checkbox-box__border {
  border: 1px solid var(--linie-stark) !important;
  border-radius: 3px !important;
}
.hr-drawer-content-wrapper:has(#data-back) .hr-checkbox:hover .hr-checkbox-box__border {
  border-color: var(--akzent) !important;
}
.hr-drawer-content-wrapper:has(#data-back) .hr-checkbox--checked .hr-checkbox-box {
  background-color: var(--akzent) !important;
}
.hr-drawer-content-wrapper:has(#data-back) .hr-checkbox--checked .hr-checkbox-box__border {
  border-color: var(--akzent) !important;
}
.hr-drawer-content-wrapper:has(#data-back) .hr-checkbox-icon path {
  fill: var(--hintergrund-karte) !important;
}
.hr-drawer-content-wrapper:has(#data-back) .hr-checkbox__label {
  color: var(--nav-hover) !important;
  font-size: 14px !important;
}

/* ════════════════════════════════════════════════════════════════
   FOOTER BUTTONS — Sub-Panel
   ════════════════════════════════════════════════════════════════ */

/* ── Stornieren (Ghost) ── */
.hr-drawer-content-wrapper:has(#data-back) #filter-level-one-btn-negative-action .hr-button__border {
  border: 1px solid var(--linie-stark) !important;
  border-radius: 6px !important;
}
.hr-drawer-content-wrapper:has(#data-back) #filter-level-one-btn-negative-action:hover .hr-button__border {
  border-color: var(--akzent) !important;
}
.hr-drawer-content-wrapper:has(#data-back) #filter-level-one-btn-negative-action .hr-button__content {
  color: var(--nav-hover) !important;
}
.hr-drawer-content-wrapper:has(#data-back) #filter-level-one-btn-negative-action:hover .hr-button__content {
  color: var(--akzent) !important;
}

/* ── Anwenden (Primary → wine) ── */
.hr-drawer-content-wrapper:has(#data-back) #filter-level-one-btn-positive-action {
  background-image: linear-gradient(var(--akzent), var(--akzent)) !important;
}
.hr-drawer-content-wrapper:has(#data-back) #filter-level-one-btn-positive-action .hr-button__border {
  border: 1px solid var(--akzent) !important;
  border-radius: 6px !important;
}
.hr-drawer-content-wrapper:has(#data-back) #filter-level-one-btn-positive-action .hr-button__content {
  color: var(--hintergrund-karte) !important;
}

/* ════════════════════════════════════════════════════════════════
   86-B ERWEITERUNG · Radio-Sub-View (Is / Is not / Is empty…)
   ════════════════════════════════════════════════════════════════ */

/* ── Radio Buttons — CSS-Var direkt auf dot-wrapper setzen ── */
.hr-drawer-content-wrapper:has(#data-back) .hr-radio .hr-radio__dot-wrapper {
  --n-box-shadow:          inset 0 0 0 1px var(--linie-stark) !important;
  --n-box-shadow-active:   inset 0 0 0 1px var(--akzent)      !important;
  --n-box-shadow-hover:    inset 0 0 0 1px var(--akzent)      !important;
  --n-box-shadow-focus:    inset 0 0 0 1px var(--akzent), 0 0 0 2px var(--akzent-ring) !important;
  --n-box-shadow-disabled: inset 0 0 0 1px var(--linie-stark) !important;
  border-radius: 50% !important;
}
/* Innerer Dot — wine via background-image Trick */
.hr-drawer-content-wrapper:has(#data-back) .hr-radio__dot.hr-radio__dot--checked {
  background-image: linear-gradient(var(--akzent), var(--akzent)) !important;
  background-color: transparent !important;
}
.hr-drawer-content-wrapper:has(#data-back) .hr-radio__label {
  color: var(--nav-hover) !important;
  font-size: 14px !important;
}

/* ── Value Label ("Value") ── */
.hr-drawer-content-wrapper:has(#data-back) .pt-3 {
  color: var(--nav-hover) !important;
  font-size: 13px !important;
}

/* ── Text-Input #data-input ── */
.hr-drawer-content-wrapper:has(#data-back) #data-input {
  --n-border:           1px solid var(--linie-stark)     !important;
  --n-border-hover:     1px solid var(--akzent)          !important;
  --n-border-focus:     1px solid var(--akzent)          !important;
  --n-box-shadow-focus: 0 0 0 2px var(--akzent-ring)     !important;
  --n-caret-color:      var(--akzent)                    !important;
}
.hr-drawer-content-wrapper:has(#data-back) #data-input .hr-input__border {
  border: 1px solid var(--linie-stark) !important;
  border-radius: 6px !important;
}
.hr-drawer-content-wrapper:has(#data-back) #data-input .hr-input__state-border {
  border-radius: 6px !important;
}

/* ============================================================
   SECTION 83 · IMPORT PAGE
   Scope: .scrollable-div-main
   ============================================================ */

/* ── Page Container ── */
.scrollable-div-main {
  background-color: var(--hintergrund-karte) !important;
}

/* ── Page Header ── */
.scrollable-div-main .hl-header .title {
  color: var(--nav-farbe) !important;
  font-weight: 700 !important;
}
.scrollable-div-main .hl-header .description {
  color: var(--text-gedaempft) !important;
}

/* ============================================================
   STEPPER
   ============================================================ */

/* ── Step: Aktiv (process) ── */
.scrollable-div-main .n-step--process-status {
  --n-indicator-border-color: var(--akzent) !important;
  --n-indicator-color:        var(--akzent) !important;
  --n-indicator-text-color:   var(--weiss) !important;
  --n-header-text-color:      var(--nav-farbe) !important;
  --n-description-text-color: var(--text-gedaempft) !important;
}
.scrollable-div-main .n-step--process-status .n-step-indicator-slot__index {
  background-color: var(--akzent) !important;
  border-color: var(--akzent) !important;
  color: var(--weiss) !important;
}
.scrollable-div-main .n-step--process-status .n-step-content-header__title {
  color: var(--nav-farbe) !important;
  font-weight: 600 !important;
}
.scrollable-div-main .n-step--process-status .n-step-content__description {
  color: var(--text-gedaempft) !important;
}

/* ── Step: Abgeschlossen (finish) ── */
.scrollable-div-main .n-step--finish-status {
  --n-indicator-border-color: var(--akzent) !important;
  --n-indicator-color:        var(--akzent) !important;
  --n-indicator-text-color:   var(--weiss) !important;
  --n-header-text-color:      var(--nav-farbe) !important;
  --n-description-text-color: var(--text-gedaempft) !important;
  --n-splitor-color:          var(--akzent) !important;
}
.scrollable-div-main .n-step--finish-status .n-step-indicator-slot {
  background-color: var(--akzent) !important;
  border-color: var(--akzent) !important;
}
.scrollable-div-main .n-step--finish-status .n-step-content-header__title {
  color: var(--nav-farbe) !important;
}
.scrollable-div-main .n-step--finish-status .n-step-splitor {
  background-color: var(--akzent) !important;
}

/* ── Step: Wartend (wait) ── */
.scrollable-div-main .n-step--wait-status {
  --n-indicator-border-color: var(--linie-stark) !important;
  --n-indicator-color:        transparent !important;
  --n-indicator-text-color:   var(--text-schwach) !important;
  --n-header-text-color:      var(--text-schwach) !important;
  --n-description-text-color: var(--text-schwach) !important;
  --n-splitor-color:          var(--linie-stark) !important;
}
.scrollable-div-main .n-step--wait-status .n-step-indicator-slot__index {
  color: var(--text-schwach) !important;
}
.scrollable-div-main .n-step--wait-status .n-step-content-header__title {
  color: var(--text-schwach) !important;
}
.scrollable-div-main .n-step--wait-status .n-step-content__description {
  color: var(--text-schwach) !important;
}

/* ── Step Splitter Linie ── */
.scrollable-div-main .n-step-splitor {
  background-color: var(--linie-stark) !important;
}

/* ============================================================
   CARDS
   ============================================================ */

.scrollable-div-main .hl-card {
  background-color: var(--weiss) !important;
  border: 1px solid var(--linie-stark) !important;
  border-radius: 8px !important;
}
.scrollable-div-main .hl-card-header {
  border-bottom: 1px solid var(--linie-stark) !important;
}
.scrollable-div-main .hl-card-header p {
  color: var(--nav-farbe) !important;
  font-weight: 600 !important;
}

/* ============================================================
   CHECKBOX GROUP ITEMS (Objekt-Auswahl Buttons)
   ============================================================ */

/* ── Default (nicht ausgewählt) ── */
.scrollable-div-main .hl-checkbox-group-item {
  border: 1px solid var(--linie-stark) !important;
  border-radius: 8px !important;
  background-color: var(--weiss) !important;
  --n-border:         1px solid var(--linie-stark) !important;
  --n-border-hover:   1px solid var(--akzent) !important;
  --n-border-focus:   1px solid var(--akzent) !important;
  --n-border-pressed: 1px solid var(--akzent) !important;
  --n-color-hover:    var(--akzent-hell) !important;
  --n-ripple-color:   var(--akzent) !important;
}
.scrollable-div-main .hl-checkbox-group-item:hover {
  border-color: var(--akzent) !important;
  background-color: var(--akzent-hell) !important;
}
/* Blauen State-Border-Effekt entfernen */
.scrollable-div-main .hl-checkbox-group-item .n-button__border {
  border: 1px solid var(--linie-stark) !important;
  border-radius: 8px !important;
}
.scrollable-div-main .hl-checkbox-group-item:hover .n-button__state-border,
.scrollable-div-main .hl-checkbox-group-item:focus .n-button__state-border,
.scrollable-div-main .hl-checkbox-group-item:active .n-button__state-border {
  border: 1px solid var(--akzent) !important;
  box-shadow: none !important;
}
/* outline + box-shadow vom GHL n-button Reset */
.scrollable-div-main .hl-checkbox-group-item,
.scrollable-div-main .hl-checkbox-group-item:hover,
.scrollable-div-main .hl-checkbox-group-item:focus,
.scrollable-div-main .hl-checkbox-group-item:active,
.scrollable-div-main .hl-checkbox-group-item:focus-visible {
  outline: none !important;
  box-shadow: none !important;
}

/* ── Aktiv / Ausgewählt ── */
.scrollable-div-main .hl-checkbox-group-item.active {
  border: 1px solid var(--akzent) !important;
  background-color: var(--akzent-hell) !important;
}
.scrollable-div-main .hl-checkbox-group-item.active .n-button__border {
  border: 1px solid var(--akzent) !important;
  border-radius: 8px !important;
}

/* ── Icons → Wine Filter ── */
.scrollable-div-main .hl-checkbox-group-item-icon img {
  filter: brightness(0) saturate(100%)
          invert(23%) sepia(60%) saturate(400%)
          hue-rotate(300deg) brightness(80%) contrast(90%) !important;
}

/* ── Item Text ── */
.scrollable-div-main .hl-checkbox-group-item .text-gray-900 {
  color: var(--nav-farbe) !important;
  font-weight: 500 !important;
}
.scrollable-div-main .hl-checkbox-group-item .hl-text-xs-regular {
  color: var(--text-gedaempft) !important;
}

/* ── Divider im Item ── */
.scrollable-div-main .hl-checkbox-group-item .n-divider--vertical {
  background-color: var(--linie-stark) !important;
  --n-color: var(--linie-stark) !important;
}

/* ── Checkbox (nicht gecheckt) ── */
.scrollable-div-main .n-checkbox {
  --n-border:         1px solid var(--linie-stark) !important;
  --n-border-checked: 1px solid var(--akzent) !important;
  --n-border-focus:   1px solid var(--akzent) !important;
  --n-color-checked:  var(--akzent) !important;
  --n-box-shadow-focus: 0 0 0 2px var(--akzent-ring) !important;
}
.scrollable-div-main .n-checkbox .n-checkbox-box__border {
  border: 1px solid var(--linie-stark) !important;
  border-radius: 3px !important;
}

/* ── Checkbox gecheckt ── */
.scrollable-div-main .n-checkbox--checked .n-checkbox-box {
  background-color: var(--akzent) !important;
  border-color: var(--akzent) !important;
}
.scrollable-div-main .n-checkbox--checked .n-checkbox-box__border {
  border-color: var(--akzent) !important;
}

/* ============================================================
   VORHERIGE IMPORTE CARD
   ============================================================ */

.scrollable-div-main .hl-card .hl-text-sm-medium {
  color: var(--nav-farbe) !important;
  font-weight: 500 !important;
}
.scrollable-div-main .hl-card .hl-text-xs-regular {
  color: var(--text-gedaempft) !important;
}
.scrollable-div-main .hl-card .dark-blue-text {
  color: var(--akzent-dunkel) !important;
  font-weight: 500 !important;
}
.scrollable-div-main .hl-card .dark-blue-text:hover {
  color: var(--akzent) !important;
  text-decoration: underline !important;
}

/* ── Checkbox Hacken → weiß (SVG img base64) ── */
.scrollable-div-main .n-checkbox--checked .n-checkbox-box img {
  filter: brightness(0) invert(1) !important;
}
.scrollable-div-main .n-checkbox--checked .n-checkbox-box .n-checkbox-icon svg path {
  fill: var(--weiss) !important;
}

/* ── Stepper Finish-Status: Hacken Icon → Wine (nicht blau) ── */
.scrollable-div-main .n-step--finish-status .n-step-indicator-slot img {
  filter: brightness(0) saturate(100%)
          invert(23%) sepia(60%) saturate(400%)
          hue-rotate(300deg) brightness(80%) contrast(90%) !important;
}

/* ── Stepper Finish-Status: Indicator Kreis border → Wine ── */
.scrollable-div-main .n-step--finish-status {
  --n-indicator-border-color: var(--akzent) !important;
  --n-indicator-text-color:   var(--akzent) !important;
  --n-splitor-color:          var(--akzent) !important;
  --n-header-text-color:      var(--nav-farbe) !important;
  --n-description-text-color: var(--text-gedaempft) !important;
}
.scrollable-div-main .n-step--finish-status .n-step-content-header__title {
  color: var(--nav-farbe) !important;
}
.scrollable-div-main .n-step--finish-status .n-step-content__description {
  color: var(--text-gedaempft) !important;
}
.scrollable-div-main .n-step--finish-status .n-step-splitor {
  background-color: var(--akzent) !important;
}

/* ============================================================
   SELECT DROPDOWN OPTIONS (teleportiert)
   n-base-select-option
   ============================================================ */

.n-base-select-option {
  color: var(--nav-hover) !important;
  background-color: var(--hintergrund-karte) !important;
}
.n-base-select-option--pending {
  background-color: var(--akzent-hell) !important;
}
.n-base-select-option--selected {
  color: var(--akzent-dunkel) !important;
  background-color: var(--akzent-hell) !important;
}
.n-base-select-option--selected .n-base-select-option__check svg path {
  fill: var(--akzent-dunkel) !important;
  color: var(--akzent-dunkel) !important;
}
.n-base-select-option:hover {
  background-color: var(--akzent-hell) !important;
  color: var(--akzent-dunkel) !important;
}
.n-base-select-option p {
  color: inherit !important;
}
.n-base-select-option span {
  color: var(--text-schwach) !important;
}

/* ============================================================
   MAPPING CARD — Pflichtfelder Inhalt
   ============================================================ */

.scrollable-div-main .hl-card-content .text-black.hl-text-sm-medium {
  color: var(--nav-farbe) !important;
  font-weight: 600 !important;
}
.scrollable-div-main .hl-card-content .hl-text-sm-normal {
  color: var(--nav-hover) !important;
}


/* ============================================================
   FOOTER
   ============================================================ */

footer:has(#back-button) {
  background-color: var(--weiss) !important;
  border-top: 1px solid var(--linie-stark) !important;
}

/* "Zurück" Button — outlined */
#back-button {
  border: 1px solid var(--linie-stark) !important;
  border-radius: 8px !important;
  color: var(--nav-hover) !important;
  background: transparent !important;
  --n-border:           1px solid var(--linie-stark) !important;
  --n-border-hover:     1px solid var(--akzent) !important;
  --n-text-color:       var(--nav-hover) !important;
  --n-text-color-hover: var(--akzent-dunkel) !important;
  --n-ripple-color:     var(--akzent) !important;
}
#back-button:hover { border-color: var(--akzent) !important; color: var(--akzent-dunkel) !important; }
#back-button .n-button__border { border: 1px solid var(--linie-stark) !important; border-radius: 8px !important; }
#back-button:hover .n-button__state-border { border: 1px solid var(--akzent) !important; }

/* "Stornieren" Button — nur Text */
#cancel-button { border: none !important; background: transparent !important; box-shadow: none !important; }
#cancel-button .n-button__content { color: var(--nav-hover) !important; }
#cancel-button:hover .n-button__content { color: var(--akzent-dunkel) !important; }

/* "Nächste" / "Weiter" Button — Wine Primary */
#next-import-button-1,
#next-import-button-2,
#next-import-button-3 {
  background-color: var(--akzent) !important;
  border: 1px solid var(--akzent) !important;
  border-radius: 8px !important;
  color: var(--weiss) !important;
  --n-color:        var(--akzent) !important;
  --n-color-hover:  var(--akzent-dunkel) !important;
  --n-border:       1px solid var(--akzent) !important;
  --n-border-hover: 1px solid var(--akzent-dunkel) !important;
  --n-text-color:   var(--weiss) !important;
  --n-ripple-color: var(--akzent) !important;
}
#next-import-button-1:hover,
#next-import-button-2:hover,
#next-import-button-3:hover { background-color: var(--akzent-dunkel) !important; border-color: var(--akzent-dunkel) !important; }
#next-import-button-1 .n-button__border,
#next-import-button-2 .n-button__border,
#next-import-button-3 .n-button__border { border: 1px solid var(--akzent) !important; border-radius: 8px !important; }

/* ============================================================
   SCHRITT 2 — UPLOAD
   ============================================================ */

/* Upload Dragger */
.scrollable-div-main #bulk-import-upload .n-upload-dragger {
  border: 1px dashed var(--linie-stark) !important;
  border-radius: 8px !important;
  background-color: var(--hintergrund-karte) !important;
  --n-dragger-border:       1px dashed var(--linie-stark) !important;
  --n-dragger-border-hover: 1px dashed var(--akzent) !important;
  --n-dragger-color:        var(--hintergrund-karte) !important;
}
.scrollable-div-main #bulk-import-upload .n-upload-dragger:hover {
  border-color: var(--akzent) !important;
  background-color: var(--akzent-hell) !important;
}
.scrollable-div-main #bulk-import-upload .hl-upload-icon svg { color: var(--text-gedaempft) !important; }
.scrollable-div-main #bulk-import-upload .hl-text-xs-medium { color: var(--nav-hover) !important; font-weight: 500 !important; }
.scrollable-div-main #bulk-import-upload .hl-text-xs-regular { color: var(--text-schwach) !important; }

/* "Wie importieren" Dropdown */
.scrollable-div-main #select-opportunity-id .n-base-selection {
  --n-border-hover:      1px solid var(--akzent) !important;
  --n-border-active:     1px solid var(--akzent) !important;
  --n-border-focus:      1px solid var(--akzent) !important;
  --n-box-shadow-active: 0 0 0 2px var(--akzent-ring) !important;
  --n-box-shadow-focus:  0 0 0 2px var(--akzent-ring) !important;
  --n-caret-color:       var(--akzent) !important;
}
.scrollable-div-main #select-opportunity-id .n-base-selection__border {
  border: 1px solid var(--linie-stark) !important;
  border-radius: 6px !important;
}
.scrollable-div-main #select-opportunity-id .n-base-selection--focus .n-base-selection__state-border,
.scrollable-div-main #select-opportunity-id .n-base-selection--active .n-base-selection__state-border {
  box-shadow: 0 0 0 2px var(--akzent-ring) !important;
  border-color: var(--akzent) !important;
}
.scrollable-div-main #select-opportunity-id .n-base-selection-input__content { color: var(--nav-hover) !important; }

/* ============================================================
   SCHRITT 3 — MAP
   ============================================================ */

.scrollable-div-main .hl-card .hl-text-xs-medium { color: var(--text-gedaempft) !important; }
.scrollable-div-main .hl-card .hl-text-sm-normal { color: var(--nav-hover) !important; }
.scrollable-div-main .hl-card .hl-text-sm-medium { color: var(--nav-farbe) !important; font-weight: 600 !important; }

/* Tabelle Header */
.scrollable-div-main .n-data-table-th {
  background-color: var(--akzent-hell) !important;
  --n-th-color:             var(--akzent-hell) !important;
  --n-th-color-hover:       var(--akzent-blass) !important;
  --n-th-text-color:        var(--nav-farbe) !important;
  --n-th-icon-color:        var(--text-schwach) !important;
  --n-th-icon-color-active: var(--akzent) !important;
}
.scrollable-div-main .n-data-table-th__title { color: var(--nav-farbe) !important; font-weight: 600 !important; }
.scrollable-div-main .n-data-table-th svg { color: var(--text-gedaempft) !important; }

/* Tabelle Rows */
.scrollable-div-main .n-data-table {
  --n-border-color:   var(--linie-stark) !important;
  --n-td-color:       var(--weiss) !important;
  --n-td-color-hover: var(--akzent-hell) !important;
  --n-td-text-color:  var(--nav-hover) !important;
  --n-loading-color:  var(--akzent) !important;
}
.scrollable-div-main .n-data-table-td { color: var(--nav-hover) !important; }
.scrollable-div-main .n-data-table-tr:hover .n-data-table-td { background-color: var(--akzent-hell) !important; }

/* Empty State */
.scrollable-div-main .n-empty .n-empty__icon svg { color: var(--text-schwach) !important; }
.scrollable-div-main .n-empty .n-empty__description { color: var(--text-schwach) !important; }

/* ============================================================
   SECTION 87 — Dashboard Add Widget Modal
   Scope: .n-card.n-modal.hl-modal
   ============================================================ */

/* ── Modal Titel & Beschreibung ── */
.n-card.hl-modal .n-card-header .hl-display-sm-semibold {
  color: var(--nav-farbe) !important;
}
.n-card.hl-modal .n-card-header .text-gray-600 {
  color: var(--text-gedaempft) !important;
}

/* ── Dashboard Select Label ── */
.n-card.hl-modal .select-label {
  color: var(--nav-hover) !important;
  font-weight: 500 !important;
}

/* ── Dashboard Select Input ── */
.n-card.hl-modal .n-select .n-base-selection {
  --n-border:            1px solid var(--linie-stark) !important;
  --n-border-hover:      1px solid var(--akzent) !important;
  --n-border-focus:      1px solid var(--akzent) !important;
  --n-border-active:     1px solid var(--akzent) !important;
  --n-box-shadow-focus:  0 0 0 2px var(--akzent-ring) !important;
  --n-box-shadow-active: 0 0 0 2px var(--akzent-ring) !important;
  --n-caret-color:       var(--akzent) !important;
  --n-loading-color:     var(--akzent) !important;
}

/* ── Widget Selector Bereich (graue Sektion) ── */
.n-card.hl-modal section[aria-labelledby="reporting_widget_selector-heading-top_widgets"] {
  background-color: var(--akzent-blass) !important;
  border-radius: 8px !important;
}

/* Titel "Ausgewählt Widgets (n)" */
.n-card.hl-modal #reporting_widget_selector-heading-top_widgets {
  color: var(--nav-hover) !important;
  font-weight: 600 !important;
}

/* Karussell-Pfeil-Buttons */
.n-card.hl-modal #reporting_widget_selector-btn-scroll_left,
.n-card.hl-modal #reporting_widget_selector-btn-scroll_right {
  --n-border:         1px solid var(--linie-stark) !important;
  --n-border-hover:   1px solid var(--akzent) !important;
  --n-border-pressed: 1px solid var(--akzent) !important;
  --n-color-hover:    var(--akzent-hell) !important;
  border-radius: 50% !important;
}
.n-card.hl-modal #reporting_widget_selector-btn-scroll_left svg,
.n-card.hl-modal #reporting_widget_selector-btn-scroll_right svg {
  color: var(--nav-hover) !important;
}
.n-card.hl-modal #reporting_widget_selector-btn-scroll_left:hover svg,
.n-card.hl-modal #reporting_widget_selector-btn-scroll_right:hover svg {
  color: var(--akzent-dunkel) !important;
}

/* ── Widget Karten ── */
.n-card.hl-modal .border-primary-700 {
  border-color: var(--akzent) !important;
  border-radius: 8px !important;
}

/* Checkbox wine — maximale Spezifität gegen inline --n-color-checked */
.n-card.hl-modal .n-checkbox--checked {
  --n-check-mark-color: var(--weiss) !important;
}
/* Direkte background-color Überschreibung — ignoriert CSS Variable */
.n-card.hl-modal .n-checkbox.n-checkbox--checked .n-checkbox-box-wrapper .n-checkbox-box {
  background-color: var(--akzent) !important;
  background:       var(--akzent) !important;
  border-color:     var(--akzent) !important;
}
/* Auch für hover/focus state */
.n-card.hl-modal .n-checkbox.n-checkbox--checked:hover .n-checkbox-box,
.n-card.hl-modal .n-checkbox.n-checkbox--checked:focus .n-checkbox-box {
  background-color: var(--akzent-dunkel) !important;
  background:       var(--akzent-dunkel) !important;
  border-color:     var(--akzent-dunkel) !important;
}
/* SVG fill weiß */
.n-card.hl-modal .n-checkbox.n-checkbox--checked .n-checkbox-box .n-checkbox-icon .check-icon,
.n-card.hl-modal .n-checkbox.n-checkbox--checked .n-checkbox-box .n-checkbox-icon .check-icon path {
  fill: var(--weiss) !important;
}

/* Widget Titel & Werte */
.n-card.hl-modal .border-primary-700 .hl-text-xs-medium,
.n-card.hl-modal .border-primary-700 .text-gray-900.font-semibold {
  color: var(--nav-farbe) !important;
}

/* ── Modal Footer ── */
.n-card.hl-modal .n-card__footer {
  border-top: 1px solid var(--linie-stark) !important;
  background-color: var(--weiss) !important;
}

/* Cancel Button (outlined) */
.n-card.hl-modal #dashboard_breadcrumb_add_widget_modal-footer_btn-cancel {
  --n-border:           1px solid var(--linie-stark) !important;
  --n-border-hover:     1px solid var(--akzent) !important;
  --n-border-pressed:   1px solid var(--akzent) !important;
  --n-border-focus:     1px solid var(--akzent) !important;
  --n-text-color:       var(--nav-hover) !important;
  --n-text-color-hover: var(--akzent-dunkel) !important;
  --n-text-color-focus: var(--akzent-dunkel) !important;
  --n-color-hover:      var(--akzent-hell) !important;
  --n-ripple-color:     var(--akzent-ring) !important;
  --n-border-radius:    8px !important;
}

/* Speichern Button (primary → wine) */
.n-card.hl-modal #dashboard_breadcrumb_add_widget_modal-footer_btn-confirm_add {
  --n-color:           var(--akzent) !important;
  --n-color-hover:     var(--akzent-dunkel) !important;
  --n-color-pressed:   var(--akzent) !important;
  --n-color-focus:     var(--akzent-dunkel) !important;
  --n-color-disabled:  var(--akzent) !important;
  --n-border:          1px solid var(--akzent) !important;
  --n-border-hover:    1px solid var(--akzent-dunkel) !important;
  --n-border-pressed:  1px solid var(--akzent) !important;
  --n-border-focus:    1px solid var(--akzent-dunkel) !important;
  --n-border-disabled: 1px solid var(--akzent) !important;
  --n-ripple-color:    var(--akzent-ring) !important;
  --n-border-radius:   8px !important;
  background-color: var(--akzent) !important;
  border-color: var(--akzent) !important;
}
.n-card.hl-modal #dashboard_breadcrumb_add_widget_modal-footer_btn-confirm_add:hover {
  background-color: var(--akzent-dunkel) !important;
  border-color: var(--akzent-dunkel) !important;
}

/* ============================================================
   SECTION 87 — Dashboard Select Dropdown
   Scope: .n-base-select-menu.n-select-menu
   (teleportiert, außerhalb des normalen DOM)
   ============================================================ */

/* ── Container ── */
.n-base-select-menu.n-select-menu {
  background-color: var(--hintergrund-karte) !important;
  border: 1px solid var(--linie-stark) !important;
  border-radius: 8px !important;
  box-shadow: 0 4px 16px var(--black-a08) !important;
  --n-color: var(--hintergrund-karte) !important;
  --n-border-radius: 8px !important;
}

/* ── Optionen ── */
.n-base-select-menu.n-select-menu .n-base-select-option {
  color: var(--nav-hover) !important;
  background-color: transparent !important;
  --n-option-text-color:         var(--nav-hover) !important;
  --n-option-text-color-active:  var(--akzent-dunkel) !important;
  --n-option-text-color-pressed: var(--akzent) !important;
  --n-option-color-pending:      var(--akzent-hell) !important;
  --n-option-color-active:       transparent !important;
  --n-option-color-active-pending: var(--akzent-hell) !important;
  --n-option-check-color:        var(--akzent-dunkel) !important;
}

.n-base-select-menu.n-select-menu .n-base-select-option--pending {
  background-color: var(--akzent-hell) !important;
  color: var(--akzent-dunkel) !important;
}

.n-base-select-menu.n-select-menu .n-base-select-option--selected {
  color: var(--akzent-dunkel) !important;
  background-color: var(--akzent-hell) !important;
}

.n-base-select-menu.n-select-menu .n-base-select-option--selected
  .n-base-select-option__check svg path {
  fill: var(--akzent-dunkel) !important;
  color: var(--akzent-dunkel) !important;
}

.n-base-select-menu.n-select-menu .n-base-select-option p {
  color: inherit !important;
}

.n-base-select-menu.n-select-menu .n-base-select-option span {
  color: var(--text-schwach) !important;
}

/* ── Action Footer ── */
.n-base-select-menu.n-select-menu .n-base-select-menu__action {
  border-top: 1px solid var(--linie-stark) !important;
  background-color: var(--hintergrund-karte) !important;
  padding: 6px 8px !important;
  --n-action-divider-color: var(--linie-stark) !important;
}

/* ── "Erstellen Dashboard" Button ── */
.n-base-select-menu.n-select-menu .n-base-select-menu__action button,
.n-base-select-menu.n-select-menu .n-base-select-menu__action .hl-text-btn {
  --n-text-color:         var(--akzent) !important;
  --n-text-color-hover:   var(--akzent-dunkel) !important;
  --n-text-color-focus:   var(--akzent-dunkel) !important;
  --n-text-color-pressed: var(--akzent) !important;
}

.n-base-select-menu.n-select-menu .n-base-select-menu__action .text-primary-600 {
  color: var(--akzent) !important;
}

.n-base-select-menu.n-select-menu .n-base-select-menu__action button:not([disabled]):hover
  .text-primary-600 {
  color: var(--akzent-dunkel) !important;
}

/* ── Ladefarbe ── */
.n-base-select-menu.n-select-menu {
  --n-loading-color: var(--akzent) !important;
}

/* ============================================================
   SECTION 88 — Massedaten bearbeiten Drawer
   State A: Feld-Auswahl  |  State B: Feld-Bearbeitung
   Scope: .hr-drawer-content.hl-drawer-content
   ============================================================ */

/* ── Drawer Shell ── */
.hr-drawer-content.hl-drawer-content {
  background-color: var(--hintergrund-karte) !important;
}

/* ── Header ── */
.hr-drawer-content.hl-drawer-content .hr-drawer-header {
  border-bottom: 1px solid var(--linie-stark) !important;
  background-color: var(--hintergrund-karte) !important;
}
.hr-drawer-content.hl-drawer-content .hl-drawer-title {
  color: var(--nav-farbe) !important;
  font-weight: 600 !important;
}
.hr-drawer-content.hl-drawer-content .hr-drawer-header__close {
  color: var(--text-gedaempft) !important;
  border-radius: 6px !important;
}
.hr-drawer-content.hl-drawer-content .hr-drawer-header__close:hover {
  color: var(--nav-farbe) !important;
  background-color: var(--akzent-hell) !important;
}

/* ============================================================
   STATE A — Feld-Auswahl (Suchfeld + Collapse-Liste)
   ============================================================ */

/* Such-Input */
.hr-drawer-content.hl-drawer-content #search-input {
  --n-border:           1px solid var(--linie-stark) !important;
  --n-border-hover:     1px solid var(--akzent) !important;
  --n-border-focus:     1px solid var(--akzent) !important;
  --n-caret-color:      var(--akzent) !important;
  --n-box-shadow-focus: 0 0 0 2px var(--akzent-ring) !important;
  --n-loading-color:    var(--akzent) !important;
  --n-border-radius:    8px !important;
}
.hr-drawer-content.hl-drawer-content #search-input .hr-input__prefix svg {
  color: var(--text-schwach) !important;
}

/* Section Heading */
.hr-drawer-content.hl-drawer-content .heading p {
  color: var(--nav-farbe) !important;
  font-weight: 600 !important;
}

/* Collapse */
.hr-drawer-content.hl-drawer-content .hr-collapse {
  --n-text-color:       var(--nav-hover) !important;
  --n-title-text-color: var(--nav-farbe) !important;
  --n-divider-color:    var(--linie-stark) !important;
  --n-arrow-color:      var(--text-gedaempft) !important;
}
.hr-drawer-content.hl-drawer-content .hr-collapse-item__header {
  border-bottom: 1px solid var(--linie-stark) !important;
  color: var(--nav-farbe) !important;
  font-weight: 600 !important;
}
.hr-drawer-content.hl-drawer-content .hr-collapse-item__header:hover {
  color: var(--akzent-dunkel) !important;
}
.hr-drawer-content.hl-drawer-content .hr-collapse-item-arrow svg path {
  fill: var(--text-gedaempft) !important;
}
.hr-drawer-content.hl-drawer-content .hr-collapse-item--active .hr-collapse-item-arrow svg path {
  fill: var(--akzent) !important;
}

/* Field Items (klickbar) */
.hr-drawer-content.hl-drawer-content .field {
  border: 1px solid var(--linie-stark) !important;
  border-radius: 8px !important;
  background-color: var(--weiss) !important;
  cursor: pointer !important;
  transition: border-color 0.2s, background-color 0.2s !important;
}
.hr-drawer-content.hl-drawer-content .field:hover {
  border-color: var(--akzent) !important;
  background-color: var(--akzent-hell) !important;
}
.hr-drawer-content.hl-drawer-content .field span {
  color: var(--nav-hover) !important;
  font-weight: 500 !important;
}
.hr-drawer-content.hl-drawer-content .field:hover span {
  color: var(--akzent-dunkel) !important;
}

/* Field Items (disabled) */
.hr-drawer-content.hl-drawer-content .field-disabled {
  border: 1px solid var(--linie-stark) !important;
  border-radius: 8px !important;
  background-color: var(--hintergrund-karte) !important;
  opacity: 0.45 !important;
  cursor: not-allowed !important;
}
.hr-drawer-content.hl-drawer-content .field-disabled span {
  color: var(--text-schwach) !important;
}

/* ============================================================
   STATE B — Feld-Bearbeitung (field-layout rows + form fields)
   ============================================================ */

/* Jede Feld-Zeile als Card */
.hr-drawer-content.hl-drawer-content .grid.field-layout {
  background-color: var(--weiss) !important;
  border: 1px solid var(--linie-stark) !important;
  border-radius: 10px !important;
  padding: 12px 14px !important;
  margin-bottom: 10px !important;
  display: flex !important;
  align-items: flex-end !important;
  gap: 10px !important;
}

/* Form Label */
.hr-drawer-content.hl-drawer-content .hr-form-item-label__text {
  color: var(--nav-farbe) !important;
  font-weight: 500 !important;
}
.hr-drawer-content.hl-drawer-content .hr-form-item-label__asterisk {
  color: var(--fehler) !important;
}

/* ── Text-Input (Wert der Gelegenheit / € etc.) ── */
.hr-drawer-content.hl-drawer-content .hr-form-item-blank .hr-input {
  --n-border:           1px solid var(--linie-stark) !important;
  --n-border-hover:     1px solid var(--akzent) !important;
  --n-border-focus:     1px solid var(--akzent) !important;
  --n-caret-color:      var(--akzent) !important;
  --n-box-shadow-focus: 0 0 0 2px var(--akzent-ring) !important;
  --n-loading-color:    var(--akzent) !important;
  --n-border-radius:    8px !important;
}
.hr-drawer-content.hl-drawer-content .hr-form-item-blank .hr-input .hr-input__prefix {
  color: var(--text-gedaempft) !important;
  font-weight: 500 !important;
}

/* ── Select-Dropdown (Pipeline, Schritt, Status …) ── */
.hr-drawer-content.hl-drawer-content .hr-form-item-blank .hr-base-selection {
  --n-border:            1px solid var(--linie-stark) !important;
  --n-border-hover:      1px solid var(--akzent) !important;
  --n-border-active:     1px solid var(--akzent) !important;
  --n-border-focus:      1px solid var(--akzent) !important;
  --n-border-radius:     8px !important;
  --n-box-shadow-active: 0 0 0 2px var(--akzent-ring) !important;
  --n-box-shadow-focus:  0 0 0 2px var(--akzent-ring) !important;
  --n-box-shadow-hover:  none !important;
  --n-caret-color:       var(--akzent) !important;
  --n-loading-color:     var(--akzent) !important;
  --n-arrow-color:       var(--text-schwach) !important;
}
.hr-drawer-content.hl-drawer-content .hr-base-selection-overlay__wrapper {
  color: var(--text-schwach) !important;
}
.hr-drawer-content.hl-drawer-content .hr-base-suffix__arrow svg path {
  fill: var(--text-schwach) !important;
}

/* ── Delete-Button (Trash Icon, pro Zeile) ── */
.hr-drawer-content.hl-drawer-content #delete-button {
  --n-border-radius: 8px !important;
  border:  1px solid var(--linie-stark) !important;
  color:   var(--text-gedaempft) !important;
  flex-shrink: 0 !important;
  transition: color 0.2s, border-color 0.2s, background-color 0.2s !important;
}
.hr-drawer-content.hl-drawer-content #delete-button:hover {
  color:            var(--fehler) !important;
  border-color:     var(--fehler) !important;
  background-color: var(--fehler-2-a06) !important;
}
.hr-drawer-content.hl-drawer-content #delete-button .hr-button__border {
  border-color: var(--linie-stark) !important;
}
.hr-drawer-content.hl-drawer-content #delete-button svg {
  stroke: currentColor !important;
}

/* ── Add-Field-Button ("+ Feld hinzufügen") ── */
.hr-drawer-content.hl-drawer-content #add-field-btn {
  --n-border-radius: 8px !important;
  border:      1px solid var(--akzent) !important;
  color:       var(--akzent) !important;
  transition:  color 0.2s, border-color 0.2s, background-color 0.2s !important;
}
.hr-drawer-content.hl-drawer-content #add-field-btn:hover {
  color:            var(--akzent-dunkel) !important;
  border-color:     var(--akzent-dunkel) !important;
  background-color: var(--akzent-hell) !important;
}
.hr-drawer-content.hl-drawer-content #add-field-btn svg {
  stroke: currentColor !important;
}

/* ============================================================
   FOOTER — Stornieren + Speichern
   ============================================================ */
.hr-drawer-content.hl-drawer-content .hr-drawer-footer {
  border-top: 1px solid var(--linie-stark) !important;
  background-color: var(--hintergrund-karte) !important;
}

/* Stornieren */
.hr-drawer-content.hl-drawer-content #negative-btn {
  --n-border-radius: 8px !important;
  border:      1px solid var(--linie-stark) !important;
  color:       var(--nav-hover) !important;
  transition:  color 0.2s, border-color 0.2s, background-color 0.2s !important;
}
.hr-drawer-content.hl-drawer-content #negative-btn:hover {
  color:            var(--akzent-dunkel) !important;
  border-color:     var(--akzent) !important;
  background-color: var(--akzent-hell) !important;
}

/* Speichern — inline --n-color override wie Section 87 pattern */
.hr-drawer-content.hl-drawer-content #positive-btn {
  --n-border-radius: 8px !important;
  --n-text-color:    var(--weiss) !important;
  border-color: var(--akzent) !important;
  background-color: var(--akzent) !important;
  background:       var(--akzent) !important;
}
.hr-drawer-content.hl-drawer-content #positive-btn:not(:disabled):hover {
  background-color: var(--akzent-dunkel) !important;
  background:       var(--akzent-dunkel) !important;
  border-color:     var(--akzent-dunkel) !important;
}
.hr-drawer-content.hl-drawer-content #positive-btn:disabled,
.hr-drawer-content.hl-drawer-content #positive-btn.hr-button--disabled {
  background-color: var(--akzent) !important;
  background:       var(--akzent) !important;
  border-color:     var(--akzent) !important;
  opacity: 0.5 !important;
}

/* ============================================================
   SECTION 89 — Pipeline-Einstellungen Seite
   Scope: #pipeline-page
   ============================================================ */

#pipeline-page {
  background-color: var(--hintergrund-seite) !important;
}

#pipeline-page .crm-opportunities-pipeline-page-header {
  background-color: var(--hintergrund-seite) !important;
}
#pipeline-page #pipeline-page-title {
  color: var(--nav-farbe) !important;
}
#pipeline-page #pipeline-page-description {
  color: var(--text-gedaempft) !important;
}

/* ── "Create Pipeline" Button → wine, Text + Icon weiß ── */
#pipeline-page #primary-blue {
  background-color: var(--akzent) !important;
  background:       var(--akzent) !important;
  border-color:     var(--akzent) !important;
}
#pipeline-page #primary-blue:hover {
  background-color: var(--akzent-dunkel) !important;
  background:       var(--akzent-dunkel) !important;
  border-color:     var(--akzent-dunkel) !important;
}
#pipeline-page #primary-blue .hr-button__border {
  border-color: var(--akzent) !important;
}
#pipeline-page #primary-blue:hover .hr-button__border {
  border-color: var(--akzent-dunkel) !important;
}
/* Text + Icon → immer weiß */
#pipeline-page #primary-blue p,
#pipeline-page #primary-blue span,
#pipeline-page #primary-blue svg,
#pipeline-page #primary-blue i {
  color: var(--base-white) !important;
  stroke: var(--base-white) !important;
}

/* ── Table Wrapper ── */
#pipeline-page #pipeline-table-wrapper {
  background-color: var(--hintergrund-karte) !important;
  border: 1px solid var(--linie-stark) !important;
  border-radius: 10px !important;
  overflow: hidden !important;
}

/* ── Table Header Bar ── */
#pipeline-page .hr-data-table-wrapper-header {
  background-color: var(--hintergrund-karte) !important;
  border-bottom: 1px solid var(--linie-stark) !important;
  padding: 8px 12px !important;
}
#pipeline-page #pipeline-table-wrapper-header-global-filter {
  --n-border:           1px solid var(--linie-stark) !important;
  --n-border-hover:     1px solid var(--akzent) !important;
  --n-border-focus:     1px solid var(--akzent) !important;
  --n-caret-color:      var(--akzent) !important;
  --n-box-shadow-focus: 0 0 0 2px var(--akzent-a20) !important;
}
#pipeline-page #pipeline-table-wrapper-header-global-filter .hr-input__prefix svg {
  color: var(--text-schwach) !important;
}

/* ── Data Table ── */
#pipeline-page #pipeline-table {
  background-color: var(--hintergrund-karte) !important;
}
#pipeline-page .hr-data-table__header tr,
#pipeline-page .hr-data-table__cell-header {
  background-color: var(--akzent-hell) !important;
  border-bottom: 1px solid var(--linie-stark) !important;
}
#pipeline-page .hr-data-table__cell-header .hr-text {
  color: var(--nav-farbe) !important;
  font-weight: 600 !important;
}
#pipeline-page .hr-data-table__body-row {
  background-color: var(--hintergrund-karte) !important;
  border-bottom: 1px solid var(--linie-stark) !important;
}
#pipeline-page .hr-data-table__body-row:hover {
  background-color: var(--akzent-hell) !important;
}
#pipeline-page .hr-data-table__body-cell .hr-text,
#pipeline-page .hr-data-table__body-cell span {
  color: var(--nav-hover) !important;
}
#pipeline-page .hr-data-table__body-cell .text-gray-400,
#pipeline-page .hr-data-table__body-cell .text-gray-500 {
  color: var(--text-schwach) !important;
}

/* ── Pipeline Actions Kebab-Button ── */
#pipeline-page #pipeline-actions-button {
  color: var(--text-gedaempft) !important;
  border-radius: 6px !important;
}
#pipeline-page #pipeline-actions-button:hover {
  color: var(--akzent-dunkel) !important;
  background-color: var(--akzent-hell) !important;
}

/* ── Table Footer / Pagination ── */
#pipeline-page .hr-data-table-wrapper-footer {
  background-color: var(--hintergrund-karte) !important;
  border-top: 1px solid var(--linie-stark) !important;
  padding: 8px 12px !important;
}
#pipeline-page .hr-data-table-wrapper-footer .hr-text {
  color: var(--text-gedaempft) !important;
