.hr-modal.ui-modal button#modal-footer-btn-negative-action:hover                     { color: var(--akzent) !important; }
.hr-modal.ui-modal button#modal-footer-btn-negative-action:hover .hr-button__border  { border-color: var(--akzent) !important; }
.hr-modal.ui-modal button#modal-footer-btn-negative-action .hr-button__state-border  { display: none !important; }

/* --------------------------------------------------
   5. Primary-Button „Speichern"
   -------------------------------------------------- */
.hr-modal.ui-modal button#modal-footer-btn-positive-action,
.hr-modal.ui-modal .hr-button.hr-button--primary-type {
  background-color: var(--akzent) !important;
  color:            var(--weiss) !important;
}
.hr-modal.ui-modal button#modal-footer-btn-positive-action .hr-button__border,
.hr-modal.ui-modal .hr-button.hr-button--primary-type .hr-button__border {
  border-color: var(--akzent) !important;
}
.hr-modal.ui-modal button#modal-footer-btn-positive-action:hover,
.hr-modal.ui-modal .hr-button.hr-button--primary-type:hover {
  background-color: var(--akzent-dunkel) !important;
}
.hr-modal.ui-modal button#modal-footer-btn-positive-action:hover .hr-button__border,
.hr-modal.ui-modal .hr-button.hr-button--primary-type:hover .hr-button__border {
  border-color: var(--akzent-dunkel) !important;
}
.hr-modal.ui-modal .hr-button.hr-button--primary-type .hr-button__state-border { display: none !important; }

/* --------------------------------------------------
   6. Pagination im Modal
   -------------------------------------------------- */
.hr-modal.ui-modal .hr-pagination-item--active {
  color:         var(--akzent) !important;
  border:        1px solid var(--akzent) !important;
  border-radius: 3px !important;
}
