.hr-modal.ui-modal .hr-pagination .hr-button:focus      { color: var(--akzent) !important; }
.hr-modal.ui-modal .hr-pagination .hr-button:hover .hr-button__border,
.hr-modal.ui-modal .hr-pagination .hr-button:focus .hr-button__border {
  border-color: var(--akzent) !important;
}
.hr-modal.ui-modal .hr-pagination .hr-button .hr-button__state-border { display: none !important; }

